function dir$m48(p){
  this.constructor(p);
}
dir$m48.prototype = new DirEvent();
dir$m48.prototype.afterInit = function(renderType){
  var p = this._dir; 

    var expForm = {
    t_tien: ['#t_tien', '[t_tien_nt]']
  }
  p.applyExpressionForm(expForm, true);

  dir$m48HiddenColumnByType(p);
  dir$m48DisabledStatusByAction(p);
  dir$m48DisabledMasterField(p);
  dir$m48LoadDataQuote(p);
  dir$m48LoadDataJob(p);
  dir$m48LoadQuy(p);
}

dir$m48.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id) {
    case 'ok':
		var t = p.valForm('t_tien_nt'), q = p.valForm('quy');
		var formattedNumber = t.toLocaleString('vi-VN');

		if (p.valForm('t_tien_nt') >= p.valForm('quy')) { 
			$.alert('Tổng tiền ứng: ' + formattedNumber + ' '+p.msg('noUng'));
			p.jObject('t_tien_nt').focus(); 			
			return false;
			Break;
		}
    default:
      break;
  }
  return true;
}

dir$m48.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_ngv':
      dir$m48HiddenColumnByType(p);
      break;
	case 'ma_job':
		dir$m48LoadDataJob(p);
	break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$m48.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$m48DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$m48LoadDataQuote(p){
var pa = p.options.parent;

}
function dir$m48LoadDataJob(p){
	var majob = p.valForm('ma_job');
	if(p.options.action == "NEW") {
		if ( majob != "" ) p.request('so_job', '',['ngay_ct','ma_job'])
		else p.valForm('so_job',"",true);
	}
}
function dir$m48LoadQuy(p){
  p.request('getquy', '', '');
}
function dir$m48DisabledMasterField(p, g){

	if (p.options.action == "NEW") {
		p.setDisabled(['ma_nt','ma_ngv', 'so_job','so_ct'], true);
	} else {
		p.setDisabled(['unit_id', 'ngay_ct', 'ma_job', 'so_job', 'so_ct'], true);
	}
}
function dir$m48HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
  //p.setColumnHidden(0, ['id_hd', 'so_ct_hd', 'ngay_ct_hd', 'ma_nt_hd', 'ty_gia_hd', 'tien_hd_nt', 'da_pb_nt', 'cl_nt'], v == 4);
}
function dir$m48DisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=5],[value=6],[value=7],[value=9]").remove();
}







