declare @d48 table(id int,line int,ma_kh varchar(32),ngay_ct datetime,so_ct varchar(32),id_hd varchar(32),tien_nt numeric(19,5),tien numeric(19,5),dien_giai nvarchar(256),status tinyint,ma_pttt varchar(32));

INSERT INTO @d48 (id, line, ma_kh, ngay_ct, so_ct, id_hd, tien_nt, tien, dien_giai, status, ma_pttt)
VALUES (@id, 1, @ma_kh, @ngay_ct, @so_ct, '', @t_tien_nt, @t_tien, @dien_giai, @status, 'CK');

exec ISWIFTStoredDeleteDataWithKey 'd48,ctct20,ctchi20', @id, '', @dOldVoucherDate
insert into d48 (id, line, ma_kh, ngay_ct, so_ct, id_hd, tien_nt, tien, dien_giai, status, ma_pttt) select * from @d48
insert into #idhd select distinct id_hd from @d48 where id_hd not in (select id from #idhd)

